#!/bin/bash
# runleg.sh <name>: one legacy strict-avg run, identical to ports run42 except --rl-engine legacy / --miles-root
cd /home/michael/work/gpu-legacy/ctl2; S=$(cat sid); P=/tmp/modal-venv/bin/python; N=$1
T=5400 $P lsbx.py exec $S "export PATH=\$HOME/.cargo/bin:\$PATH; cd /work/yeto && export PYTHONPATH=/opt/miles-legacy:/work/yeto:/work/harness:\$PYTHONPATH && rm -rf /work/out/$N && mkdir -p /work/out/$N && nvidia-smi --query-gpu=name,driver_version,memory.total --format=csv > /work/out/$N/gpu.txt; date -u +%s > /work/out/$N/t_start; python scripts/benchmark_rl.py --model Qwen/Qwen3-0.6B --model-revision c1899de289a04d12100db370d81485cdf75e47ca --data /work/data/gsm8k.jsonl --reward-function gsm8k_reward:score --arms federated --islands 2 --gpus-per-island 1 --global-rounds 3 --groups-per-island 4 --samples-per-group 8 --seeds 17 --rollout-max-response-len 384 --seq-len 1024 --lora-r 16 --lora-targets all-linear --eval-prompts 8 --eval-samples-per-prompt 1 --pass-k 1 --eval-device cuda --miles-root /opt/miles-legacy --apply-chat-template-kwargs '{\"enable_thinking\": false}' --trust-remote-code --rl-engine legacy --arm-timeout-min 45 --work-dir /work/out/$N/work --report-dir /work/out/$N/report > /work/out/$N/benchmark.log 2>&1; echo rc=\$? | tee /work/out/$N/rc; date -u +%s > /work/out/$N/t_end; tail -5 /work/out/$N/benchmark.log; tar czf /tmp/$N.tgz --exclude='*.pt' --exclude='*.safetensors' --exclude='*.f32' --exclude='state.ckpt*' -C /work/out $N" 2>&1 | grep -v -i deprec
E=/home/michael/yeto/openspec/changes/rl-engine-ports/evidence/2026-09-29-legacy-baseline-v2/$N; mkdir -p $E
$P lsbx.py get $S /tmp/$N.tgz /home/michael/work/gpu-legacy/ctl2/$N.tgz 2>&1 | grep -v -i deprec; tar xzf $N.tgz -C $E --strip-components=1; echo copied $E
